/bin/bash -lc "python3 - <<'PY'
import json,re,collections
from pathlib import Path
p=json.loads(Path('packet.json').read_text())
g=collections.defaultdict(list)
for i in p['items']:
    q=i['question']
    if q.startswith('Which Rel-'):
        m=re.search(r'Which Rel-(\\d+) change requests that modify clause (.*?) of TS ([\\d.]+)',q)
        g['release_clause'].append([i['id'],*m.groups()])
    elif q.startswith('In which'):
        g['pack_lookup'].append([i['id'],*re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()])
    elif q.startswith('TSG RAN'):
        g['pack_members'].append([i['id'],re.search(r'RP-\\d+',q).group()])
    elif q.startswith('Change request'):
        g['disposition_pack'].append([i['id'],*re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()])
    elif q.startswith('Trace'):
        g['trace_clauses'].append([i['id'],*re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',q).groups()])
    elif q.startswith('RAN2 recorded'):
        g['revisions'].append([i['id'],re.search(r'R2-\\d+',q).group()])
    else: raise ValueError(q)
for k,v in g.items():
    print(k,len(v))
    print(json.dumps(v,ensure_ascii=False,separators=(',',':')))
PY"

